function id(){return Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}
function monthKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`}
function defaultCategories(){return [...EXPENSE_CATS.map(x=>({id:id(),name:x[0],nameZh:x[2],emoji:x[1],kind:"expense"})),...INCOME_CATS.map(x=>({id:id(),name:x[0],nameZh:x[2],emoji:x[1],kind:"income"}))]}
const defaultData={language:"id",currency:"IDR",theme:"light",hidden:false,walletHidden:{cash:false,bank:false,ewallet:false},accounts:[{id:id(),name:"Bank Utama",type:"bank",openingBalance:0},{id:id(),name:"E-Wallet",type:"ewallet",openingBalance:0},{id:id(),name:"Tunai",type:"cash",openingBalance:0}],categories:defaultCategories(),transactions:[],recurring:[],budget:0,target:{name:"",amount:0,progress:0},targets:[],notes:[],selectedDate:today(),calendarMonth:monthKey()};
function load(){try{const raw=JSON.parse(localStorage.getItem(KEY)||"null");if(!raw)return structuredClone(defaultData);const x={...structuredClone(defaultData),...raw};x.walletHidden={...structuredClone(defaultData.walletHidden),...(raw.walletHidden||{})};x.accounts=(raw.accounts||structuredClone(defaultData.accounts)).map(a=>({...a,openingBalance:Number(a.openingBalance||0)}));x.categories=(raw.categories||structuredClone(defaultData.categories)).map(c=>({...c,emoji:c.emoji||CAT_ICONS[c.name]||"📝",nameZh:c.nameZh||CAT_ZH[c.name]||c.name}));x.transactions=raw.transactions||[];x.recurring=raw.recurring||[];x.budget=Number(raw.budget||0);x.target=raw.target||{name:"",amount:0,progress:0};x.targets=Array.isArray(raw.targets)?raw.targets:(x.target&&Number(x.target.amount||0)?[x.target]:[]);x.notes=(raw.notes||[]).map(n=>({...n,done:!!n.done,doneMonth:n.doneMonth||null,text:String(n.text||"")})).filter(n=>n.text.trim());return x}catch{return structuredClone(defaultData)}}
