function t(){return T[data.language]}
function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function categoryByName(name){return data.categories.find(c=>c.name===name)}
function catLabel(name){const c=categoryByName(name);return data.language==="zh"?(c?.nameZh||CAT_ZH[name]||name):name}
const ASSET_ICONS={Rumah:"home.png",Transfer:"transfer.png",cash:"cash.png",bank:"bank.png",ewallet:"ewallet.png",income:"income.png",expense:"expense.png",transfer:"transfer.png",note:"note.png",Makan:"makan.png",Jajan:"jajan.png",Belanja:"belanja.png",Online:"online.png",Transport:"transport.png",Tagihan:"tagihan.png",Kesehatan:"kesehatan.png",Hiburan:"hiburan.png",Liburan:"liburan.png",Gaji:"gaji.png",Bonus:"bonus.png",Hadiah:"hadiah.png",Lainnya_expense:"lainnya-expense.png",Lainnya_income:"lainnya-income.png"};
function assetIcon(file,cls="ui-icon",alt=""){return `<img class="${cls}" src="${file}" alt="${esc(alt)}" aria-hidden="true">`}
function categoryAsset(name){const c=categoryByName(name);if(!c)return ASSET_ICONS[name]||null;if(name==="Lainnya")return c.kind==="income"?ASSET_ICONS.Lainnya_income:ASSET_ICONS.Lainnya_expense;return ASSET_ICONS[name]||(typeof c.emoji==="string"&&c.emoji.endsWith(".png")?c.emoji:"feature-other.png")}
function categoryVisual(name,cls="ui-icon"){return assetIcon(categoryAsset(name)||"feature-other.png",cls,name)}
function typeVisual(type,cls="ui-icon"){return assetIcon(ASSET_ICONS[type]||"feature-other.png",cls,type)}
function catIcon(name){return categoryVisual(name)}
function categoryPicker(mountId,inputId,items,selected="",onChange){
  const current=items.find(i=>String(i.value)===String(selected))||items[0];
  const icon=current?.iconFile||"feature-other.png";
  const label=current?.label||"";
  return `<div class="category-picker" id="${mountId}"><input type="hidden" id="${inputId}" value="${esc(selected)}"><button type="button" class="category-picker-btn"><span class="category-picker-current">${assetIcon(icon,"category-picker-icon",label)}<span>${esc(label)}</span></span><span class="category-picker-chevron">⌄</span></button><div class="category-picker-menu">${items.map(i=>`<button type="button" class="category-picker-option" data-value="${esc(i.value)}">${assetIcon(i.iconFile||"feature-other.png","category-picker-icon",i.label)}<span>${esc(i.label)}</span></button>`).join("")}</div></div>`;
}
function bindCategoryPicker(mountId,inputId,items,selected,onChange){
  const root=document.getElementById(mountId); if(!root)return;
  const input=document.getElementById(inputId); if(!input)return;
  const current=root.querySelector(".category-picker-current");
  const setValue=value=>{
    input.value=String(value??"");
    const item=items.find(i=>String(i.value)===String(value))||items[0];
    if(item&&current)current.innerHTML=assetIcon(item.iconFile||"feature-other.png","category-picker-icon",item.label)+`<span>${esc(item.label)}</span>`;
    root.classList.remove("open","open-up");
    if(onChange)onChange(input.value);
  };
  root.querySelector(".category-picker-btn")?.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();document.querySelectorAll(".category-picker.open").forEach(el=>{if(el!==root){el.classList.remove("open","open-up")}});const opening=!root.classList.contains("open");root.classList.toggle("open",opening);root.classList.remove("open-up");if(opening){requestAnimationFrame(()=>{const menu=root.querySelector(".category-picker-menu"),vv=window.visualViewport,top=vv?.offsetTop||0,bottom=top+(vv?.height||window.innerHeight),r=root.getBoundingClientRect();if(r.bottom+Math.min(menu?.scrollHeight||220,220)+12>bottom&&r.top>top+120)root.classList.add("open-up");keepElementVisible(root.querySelector(".category-picker-btn"));if(menu){const available=Math.max(120,bottom-(root.classList.contains("open-up")?top+12:r.bottom+12));menu.style.maxHeight=`${Math.min(250,available)}px`}})}});
  root.querySelectorAll(".category-picker-option").forEach(btn=>btn.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();setValue(btn.dataset.value)}));
  setValue(selected);
}
function setCategoryPickerValue(inputId,value){const input=document.getElementById(inputId);if(!input)return;input.value=String(value??"");const root=input.closest(".category-picker");if(!root)return;const btn=root.querySelector(`.category-picker-option[data-value="${CSS.escape(String(value??""))}"]`);if(btn)btn.click();}
document.addEventListener("click",()=>document.querySelectorAll(".category-picker.open").forEach(el=>el.classList.remove("open","open-up")));
function money(n){const locale=data.currency==="IDR"?"id-ID":data.currency==="MYR"?"ms-MY":"zh-TW";const digits=data.currency==="MYR"?2:0;return new Intl.NumberFormat(locale,{style:"currency",currency:data.currency,maximumFractionDigits:digits,minimumFractionDigits:digits}).format(Number(n)||0)}
function currentMonthTx(){const m=monthKey();return data.transactions.filter(x=>x.date?.slice(0,7)===m)}
function totals(){return currentMonthTx().reduce((o,x)=>{if(x.type==="income")o.in+=+x.amount;if(x.type==="expense")o.ex+=+x.amount;return o},{in:0,ex:0})}
function accountOpeningForCurrentMonth(account){const start=monthKey()+"-01";let balance=Number(account.openingBalance||0);for(const x of data.transactions){if(!x.date||x.date>=start)continue;const amount=Number(x.amount)||0;if(x.type==="income"&&x.accountId===account.id)balance+=amount;else if(x.type==="expense"&&x.accountId===account.id)balance-=amount;else if(x.type==="transfer"){if(x.from===account.id)balance-=amount;if(x.to===account.id)balance+=amount}}return balance}
function recalc(){data.accounts.forEach(a=>a.balance=Number(a.openingBalance||0));for(const x of data.transactions){if(x.type==="income"){const a=data.accounts.find(a=>a.id===x.accountId);if(a)a.balance+=+x.amount}else if(x.type==="expense"){const a=data.accounts.find(a=>a.id===x.accountId);if(a)a.balance-=+x.amount}else if(x.type==="transfer"){const a=data.accounts.find(a=>a.id===x.from),b=data.accounts.find(a=>a.id===x.to);if(a)a.balance-=+x.amount;if(b)b.balance+=+x.amount}}}
function persist(renderNow=true){localStorage.setItem(KEY,JSON.stringify(data));if(renderNow)render()}
function updateVisibleViewport(){const vv=window.visualViewport;const height=Math.max(240,Math.round(vv?.height||window.innerHeight));const top=Math.max(0,Math.round(vv?.offsetTop||0));document.documentElement.style.setProperty("--visible-height",`${height}px`);document.documentElement.style.setProperty("--visible-top",`${top}px`);}
function keepElementVisible(el){if(!el||!modal.classList.contains("open"))return;const card=modal.querySelector(".modal-card");if(!card)return;requestAnimationFrame(()=>{const rect=el.getBoundingClientRect(),vv=window.visualViewport,visibleTop=vv?.offsetTop||0,visibleBottom=visibleTop+(vv?.height||window.innerHeight);if(rect.bottom>visibleBottom-18)card.scrollTop+=rect.bottom-(visibleBottom-18);else if(rect.top<visibleTop+12)card.scrollTop-=((visibleTop+12)-rect.top);});}
function openModal(title,body){document.querySelectorAll(".wallet-balance-toggle").forEach(el=>el.remove());returnScroll=window.scrollY;document.getElementById("modalTitle").textContent=title;document.getElementById("modalBody").innerHTML=body;updateVisibleViewport();modal.classList.add("open");const card=modal.querySelector(".modal-card");if(card)card.scrollTop=0}
// Keep focused form controls above the mobile keyboard, especially the note field.
document.addEventListener("focusin",e=>{const target=e.target;if(!target.matches("input,textarea,select"))return;const card=target.closest(".modal-card");if(!card)return;setTimeout(()=>{const r=target.getBoundingClientRect(),v=window.visualViewport,visibleBottom=v?v.offsetTop+v.height:window.innerHeight;if(r.bottom>visibleBottom-24||r.top<24)target.scrollIntoView({block:"center",behavior:"smooth"})},320)});
updateVisibleViewport();window.addEventListener("resize",updateVisibleViewport,{passive:true});window.visualViewport?.addEventListener("resize",()=>{updateVisibleViewport();keepElementVisible(document.activeElement)},{passive:true});window.visualViewport?.addEventListener("scroll",updateVisibleViewport,{passive:true});document.addEventListener("focusin",e=>{if(e.target.matches("input,select,textarea")){updateVisibleViewport();setTimeout(()=>keepElementVisible(e.target),80);setTimeout(()=>keepElementVisible(e.target),260)}});
function closeModal(restore=true){modal.classList.remove("open");if(restore)setTimeout(()=>window.scrollTo(0,returnScroll),0)}
document.getElementById("closeModal").onclick=()=>closeModal();modal.onclick=e=>{if(e.target===modal)closeModal()};
function parseAmountValue(value){let v=String(value??"").trim();if(!v)return 0;if(data.currency==="MYR"){v=v.replace(/\s/g,"");if(v.includes(",")&&v.includes(".")){if(v.lastIndexOf(".")>v.lastIndexOf(","))v=v.replace(/,/g,"");else v=v.replace(/\./g,"").replace(",",".")}else if(v.includes(",")){const tail=v.split(",").pop();v=tail.length<=2?v.replace(/,/g,"."):v.replace(/,/g,"")}return Number(v.replace(/[^0-9.]/g,""))||0}return Number(v.replace(/[^0-9]/g,""))||0}
function formatAmountInputValue(value){const n=parseAmountValue(value);if(data.currency==="MYR"){return new Intl.NumberFormat("en-MY",{minimumFractionDigits:2,maximumFractionDigits:2}).format(n)}return new Intl.NumberFormat("id-ID",{maximumFractionDigits:0,minimumFractionDigits:0}).format(n)}
function amountInput(idName,value=0){return `<input id="${idName}" class="amount-input" type="text" inputmode="decimal" autocomplete="off" value="${formatAmountInputValue(value)}">`}
function wireAmount(idName){const el=document.getElementById(idName);if(!el)return;el.addEventListener("focus",()=>{if(parseAmountValue(el.value)===0)el.value=""});el.addEventListener("blur",()=>{el.value=el.value.trim()===""?formatAmountInputValue(0):formatAmountInputValue(el.value)});el.addEventListener("input",()=>{let raw=el.value;if(data.currency==="MYR"){raw=raw.replace(/[^0-9.,]/g,"");const lastDot=raw.lastIndexOf("."),lastComma=raw.lastIndexOf(",");if(lastDot>=0&&lastComma>=0){const decimalPos=Math.max(lastDot,lastComma);raw=raw.slice(0,decimalPos).replace(/[.,]/g,"")+"."+raw.slice(decimalPos+1).replace(/[.,]/g,"")}else if(lastComma>=0){const tail=raw.slice(lastComma+1);raw=tail.length<=2?raw.slice(0,lastComma).replace(/[.,]/g,"")+"."+tail.replace(/[.,]/g,""):raw.replace(/,/g,"")}else if((raw.match(/\./g)||[]).length>1){const pos=raw.lastIndexOf(".");raw=raw.slice(0,pos).replace(/\./g,"")+"."+raw.slice(pos+1).replace(/\./g,"")}const parts=raw.split(".");let whole=(parts[0]||"").replace(/\D/g,"").replace(/^0+(?=\d)/,"");let dec=parts.length>1?parts.slice(1).join("").replace(/\D/g,"").slice(0,2):undefined;el.value=whole+(dec!==undefined?"."+dec:"");if(whole)el.value=new Intl.NumberFormat("en-MY",{maximumFractionDigits:0}).format(Number(whole))+(dec!==undefined?"."+dec:"")}else{const digits=raw.replace(/\D/g,"").replace(/^0+(?=\d)/,"");el.value=digits?new Intl.NumberFormat("id-ID",{maximumFractionDigits:0}).format(Number(digits)):""}})}
function toast(msg){const el=document.createElement("div");el.className="toast";el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.classList.add("show"),20);setTimeout(()=>{el.classList.remove("show");setTimeout(()=>el.remove(),220)},1700)}
