function renderCalendar(){const [yy,mm]=data.calendarMonth.split("-").map(Number);const first=new Date(yy,mm-1,1),days=new Date(yy,mm,0).getDate(),start=(first.getDay()+6)%7;const names=data.language==="zh"?["一","二","三","四","五","六","日"]:["Sn","Sl","Rb","Km","Jm","Sb","Mg"];document.getElementById("calendarMonthLabel").textContent=new Intl.DateTimeFormat(data.language==="zh"?"zh-TW":"id-ID",{month:"long",year:"numeric"}).format(first);document.getElementById("calendarWeekdays").innerHTML=names.map(n=>`<span>${n}</span>`).join("");const counts={};data.transactions.forEach(x=>counts[x.date]=(counts[x.date]||0)+1);let html=Array(start).fill('<button class="cal-day empty"></button>').join("");for(let d=1;d<=days;d++){const ds=`${yy}-${String(mm).padStart(2,"0")}-${String(d).padStart(2,"0")}`;html+=`<button class="cal-day ${counts[ds]?"has-tx":""} ${data.selectedDate===ds?"selected":""}" onclick="selectDate('${ds}')">${d}${counts[ds]?"<i></i>":""}</button>`}document.getElementById("calendarGrid").innerHTML=html;renderCalendarFilters();renderSelectedDateTx()}
