    const list=data.notes||[];
    document.getElementById("modalBody").innerHTML=`<div class="notes-wrap"><button class="primary button-with-icon" id="addNoteBtn"><img src="plus.png" class="button-img" alt="">${esc(x.noteAdd)}</button>${list.length?`<div class="notes-list">${list.map(n=>`<div class="note-row ${n.done?"done":""}"><label class="note-check"><input type="checkbox" ${n.done?"checked":""} onchange="toggleNote('${n.id}',this.checked)"><span class="check-box"><img src="${n.done?"checkbox-on.png":"checkbox-off.png"}" class="checkbox-img" alt=""></span></label><button class="note-text" onclick="editNote('${n.id}')">${esc(n.text)}</button><button class="note-delete" aria-label="${esc(x.delete)}" title="${esc(x.delete)}" onclick="deleteNote('${n.id}')">${assetIcon("delete.png","mini-action-img",x.delete)}</button></div>`).join("")}</div>`:`<div class="empty small-empty">${x.noteEmpty}</div>`}</div>`;
