    ["Makan","makan.png","飲食"],["Jajan","jajan.png","點心"],["Belanja","belanja.png","購物"],["Online","online.png","網購"],["Transport","transport.png","交通"],["Rumah","home.png","居家"],["Transfer","transfer.png","轉帳"],["Tagihan","tagihan.png","帳單"],["Kesehatan","kesehatan.png","醫療"],["Hiburan","hiburan.png","娛樂"],["Liburan","liburan.png","旅遊"],["Gaji","gaji.png","薪資"],["Bonus","bonus.png","獎金"],["Hadiah","hadiah.png","禮物"],["Uang","cash.png","金錢"],["Bank","bank.png","銀行"],["E-Wallet","ewallet.png","電子錢包"],["Catatan","note.png","備忘"],["Lainnya","feature-other.png","其他"]
