  openModal(existing?x.edit:x.add+" "+x.category,`<div class="form-grid category-edit-form"><div class="field"><label for="catName">${labelId}</label><input id="catName" maxlength="30" value="${valId}" placeholder="${zh?"例如：咖啡":"Contoh: Kopi"}" ${zh?"":"required"}></div><div class="field"><label for="catNameZh">${labelZh}</label><input id="catNameZh" maxlength="30" value="${valZh}" placeholder="${zh?"印尼文名稱，可留空":"Boleh dikosongkan"}" ${zh?"":""}></div><div class="field"><label>${x.categoryIcon}</label><div class="selected-icon-preview" id="selectedIconPreview">${assetIcon(selectedIcon,"form-icon-preview",x.categoryIcon)}</div><input type="hidden" id="catIcon" value="${selectedIcon}">${iconGrid()}</div><div class="field"><label>${x.type}</label><select id="catKind"><option value="expense">${x.expenseType}</option><option value="income">${x.incomeType}</option></select></div><button class="primary" id="saveCategory">${x.save}</button>${existing?`<button class="primary category-delete-btn" id="deleteCategory">${x.delete}</button>`:""}</div>`);
  document.getElementById("catKind").value=c.kind;
