function backupData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`catatan-keuangan-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast(t().exported)}
function restoreData(e){
  const f=e.target.files?.[0];
  if(!f)return;
  const reader=new FileReader();
  reader.onload=()=>{
    try{
      const x=JSON.parse(reader.result);
      const validObject=x&&typeof x==="object"&&!Array.isArray(x);
      if(!validObject||!Array.isArray(x.accounts)||!Array.isArray(x.categories)||!Array.isArray(x.transactions))throw new Error("Invalid backup schema");
      if((x.recurring!==undefined&&!Array.isArray(x.recurring))||(x.notes!==undefined&&!Array.isArray(x.notes))||(x.targets!==undefined&&!Array.isArray(x.targets)))throw new Error("Invalid optional backup data");
      if(x.language!==undefined&&!['id','zh'].includes(x.language))throw new Error("Invalid language");
      if(x.currency!==undefined&&!['IDR','MYR','NTD'].includes(x.currency))throw new Error("Invalid currency");
      if(x.theme!==undefined&&!['light','dark'].includes(x.theme))throw new Error("Invalid theme");
      const idsAreUnique=list=>{const ids=list.map(v=>v?.id);return ids.every(v=>typeof v==="string"&&v.trim())&&new Set(ids).size===ids.length};
      if(!x.accounts.length||!idsAreUnique(x.accounts)||!x.accounts.every(a=>typeof a.name==="string"&&['cash','bank','ewallet'].includes(a.type)&&Number.isFinite(Number(a.openingBalance??0))))throw new Error("Invalid accounts");
      if(!idsAreUnique(x.categories)||!x.categories.every(c=>typeof c.name==="string"&&c.name.trim()&&['expense','income'].includes(c.kind)&&(c.nameZh===undefined||typeof c.nameZh==="string")))throw new Error("Invalid categories");
      if(!idsAreUnique(x.transactions)||!x.transactions.every(tx=>{
        if(!['expense','income','transfer'].includes(tx.type)||!Number.isFinite(Number(tx.amount))||Number(tx.amount)<=0||typeof tx.date!=="string"||!/^\d{4}-\d{2}-\d{2}$/.test(tx.date))return false;
        const d=new Date(tx.date+"T00:00:00Z");if(Number.isNaN(d.getTime())||d.toISOString().slice(0,10)!==tx.date)return false;
        if(tx.type==="transfer")return typeof tx.from==="string"&&typeof tx.to==="string"&&tx.from!==tx.to;
        return typeof tx.accountId==="string";
      }))throw new Error("Invalid transactions");
      if(!(x.recurring||[]).every(r=>r&&typeof r==="object"&&(r.id===undefined||typeof r.id==="string")&&Number.isFinite(Number(r.amount??0))&&Number(r.amount??0)>=0&&(r.day===undefined||(Number.isInteger(Number(r.day))&&Number(r.day)>=1&&Number(r.day)<=31))))throw new Error("Invalid recurring data");
      if(!(x.notes||[]).every(n=>n&&typeof n==="object"&&typeof n.text==="string"&&(n.id===undefined||typeof n.id==="string")))throw new Error("Invalid notes");
      if(!(x.targets||[]).every(g=>g&&typeof g==="object"&&typeof g.name==="string"&&Number.isFinite(Number(g.amount))&&Number(g.amount)>=0&&Number.isFinite(Number(g.progress??0))))throw new Error("Invalid savings targets");
      const imported={...structuredClone(defaultData),...x};
      imported.walletHidden={...structuredClone(defaultData.walletHidden),...(x.walletHidden||{})};
      imported.accounts=x.accounts.map(a=>({...a,openingBalance:Number(a.openingBalance??0)}));
      imported.categories=x.categories.map(c=>({...c,emoji:c.emoji||CAT_ICONS[c.name]||"feature-other.png",nameZh:c.nameZh||CAT_ZH[c.name]||c.name}));
      imported.transactions=x.transactions.map(tx=>({...tx,amount:Number(tx.amount),note:String(tx.note||"")}));
      imported.recurring=Array.isArray(x.recurring)?x.recurring:[];
      imported.notes=(Array.isArray(x.notes)?x.notes:[]).map(n=>({...n,done:!!n.done,doneMonth:n.doneMonth||null,text:String(n.text||"")})).filter(n=>n.text.trim());
      imported.budget=Number(x.budget||0);
      imported.target=x.target||{name:"",amount:0,progress:0};
      imported.targets=Array.isArray(x.targets)?x.targets:(imported.target&&Number(imported.target.amount||0)?[imported.target]:[]);
      data=imported;persist();closeModal();toast(t().imported);
    }catch{alert(data.language==="zh"?"備份檔案無效或格式不相容。":"File backup tidak valid atau formatnya tidak cocok.")}
    finally{e.target.value=""}
  };
  reader.readAsText(f);
}
