function shiftCalendar(step){const [y,m]=data.calendarMonth.split("-").map(Number);const d=new Date(y,m-1+step,1);data.calendarMonth=monthKey(d);data.selectedDate=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-01`;persist()}
